/**
 * Bounded Asynchronous Task Queue with Backpressure, Cancellation,
 * Graceful Shutdown, and Typed Errors.
 *
 * Features:
 * - Bounded queue size with configurable backpressure strategy (block, reject, drop)
 * - Task cancellation via AbortSignal
 * - Graceful shutdown (drain pending tasks) and immediate shutdown
 * - Typed error hierarchy
 * - Deterministic behavior for testing
 * - Concurrency control
 * - Task lifecycle events
 */

// ─── Typed Errors ────────────────────────────────────────────────────────────

export class TaskQueueError extends Error {
  constructor(message: string, public readonly code: string) {
    super(message);
    this.name = "TaskQueueError";
  }
}

export class QueueFullError extends TaskQueueError {
  constructor(message = "Queue is full") {
    super(message, "QUEUE_FULL");
    this.name = "QueueFullError";
  }
}

export class TaskCancelledError extends TaskQueueError {
  constructor(message = "Task was cancelled") {
    super(message, "TASK_CANCELLED");
    this.name = "TaskCancelledError";
  }
}

export class QueueShutdownError extends TaskQueueError {
  constructor(message = "Queue is shut down") {
    super(message, "QUEUE_SHUTDOWN");
    this.name = "QueueShutdownError";
  }
}

export class TaskExecutionError extends TaskQueueError {
  constructor(
    message: string,
    public readonly originalError: unknown,
    public readonly taskId: string,
  ) {
    super(message, "TASK_EXECUTION");
    this.name = "TaskExecutionError";
  }
}

// ─── Types ───────────────────────────────────────────────────────────────────

export type BackpressureStrategy = "block" | "reject" | "drop";

export type TaskStatus =
  | "pending"
  | "running"
  | "completed"
  | "failed"
  | "cancelled";

export interface TaskOptions {
  /** Unique identifier for the task. Auto-generated if not provided. */
  id?: string;
  /** AbortSignal for cancellation. */
  signal?: AbortSignal;
  /** Priority (lower number = higher priority). Default: 0. */
  priority?: number;
  /** Timeout in milliseconds. 0 or undefined means no timeout. */
  timeoutMs?: number;
  /** Maximum number of retries on failure. Default: 0. */
  maxRetries?: number;
  /** Delay between retries in milliseconds. Default: 0. */
  retryDelayMs?: number;
}

export interface TaskResult<T> {
  taskId: string;
  status: TaskStatus;
  value?: T;
  error?: TaskQueueError;
  startedAt?: number;
  completedAt?: number;
  durationMs?: number;
}

export interface QueueStats {
  pending: number;
  running: number;
  completed: number;
  failed: number;
  cancelled: number;
  totalEnqueued: number;
  totalProcessed: number;
}

export type TaskFn<T> = (
  signal: AbortSignal,
  attempt: number,
) => Promise<T> | T;

export interface QueueEvents {
  taskEnqueued: (taskId: string) => void;
  taskStarted: (taskId: string) => void;
  taskCompleted: (result: TaskResult<unknown>) => void;
  taskFailed: (result: TaskResult<unknown>) => void;
  taskCancelled: (taskId: string) => void;
  queueFull: () => void;
  queueDrained: () => void;
  queueShutdown: () => void;
}

// ─── Internal Task Representation ────────────────────────────────────────────

interface InternalTask<T> {
  id: string;
  fn: TaskFn<T>;
  options: Required<Omit<TaskOptions, "signal">> & { signal?: AbortSignal };
  status: TaskStatus;
  resolve: (result: TaskResult<T>) => void;
  reject: (error: TaskQueueError) => void;
  promise: Promise<TaskResult<T>>;
  startedAt?: number;
  completedAt?: number;
  attempt: number;
  maxRetries: number;
  retryDelayMs: number;
  timeoutMs: number;
  priority: number;
  abortController: AbortController;
  timeoutId?: ReturnType<typeof setTimeout>;
  retryTimeoutId?: ReturnType<typeof setTimeout>;
}

